// Fakes for the executor's two seams plus the sdk.MetadataSource capability.
// Real instances over subprocesses are impractical here (plugin.Manager needs
// a live handshake; grabberImpl is package main of another binary), so the
// fakes implement the exact interface shapes the executor consumes — the same
// R8 seam discipline internal/enrich's tests use.

// grabPayload is the "fresh frame" the fake Convert writes to the thumbnail
// path; the stop-position test asserts these bytes replaced the stale ones.
var grabPayload = []byte("stop-frame-jpeg-bytes")

// fakeThumbStore serves one stored item (or an error) over the thumbStore seam.
type fakeThumbStore struct {
	item store.Item
	err  error
}

func (f *fakeThumbStore) GetItem(context.Context, string) (store.Item, error) {
	if f.err != nil {
		return store.Item{}, f.err
	}
	return f.item, nil
}

// fakeThumbSources resolves the seam to a fake source (or an error — the
// plugin-unavailable path).
type fakeThumbSources struct {
	src sdk.MetadataSource
	err error
}

func (f *fakeThumbSources) MetadataSource(string, string) (sdk.MetadataSource, error) {
	if f.err != nil {
		return nil, f.err
	}
	return f.src, nil
}

// fakeGrabber is a sdk.MetadataSource fake mirroring frame-grabber's shapes:
// Match rebuilds the query from the parsed facts it is handed; Convert
// records the query (seek_seconds especially) and optionally writes
// grabPayload to a test-chosen path — standing in for the real ffmpeg write.
type fakeGrabber struct {
	mu         sync.Mutex
	applies    bool
	reason     string
	matchErr   error
	convertErr error
	warnings   []string
	writePath  string

	parsed   []*structpb.Struct // per Match: the base it was handed
	converts []*structpb.Struct // per Convert: the query it received
	grabs    chan struct{}      // one buffered send per Convert invocation
}

func newFakeGrabber(applies bool) *fakeGrabber {
	return &fakeGrabber{applies: applies, grabs: make(chan struct{}, 64)}
}

func (g *fakeGrabber) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	g.mu.Lock()
	defer g.mu.Unlock()
	if g.matchErr != nil {
		return nil, g.matchErr
	}
	g.parsed = append(g.parsed, req.GetItem().GetParsed())
	if !g.applies {
		return &metadatav1.MatchResult{Applies: false, Reason: g.reason}, nil
	}
	f := req.GetItem().GetParsed().GetFields()
	q := map[string]any{"absolute_path": f["absolute_path"].GetStringValue()}
	if rp := f["relative_path"].GetStringValue(); rp != "" {
		q["relative_path"] = rp
	}
	if srel := f["series_relative_path"].GetStringValue(); srel != "" {
		q["series_relative_path"] = srel
	}
	if d := f["probe_duration_seconds"].GetNumberValue(); d > 0 {
		q["probe_duration_seconds"] = d
	}
	query, _ := structpb.NewStruct(q)
	return &metadatav1.MatchResult{Applies: true, Query: query, Confidence: 1.0}, nil
}

func (*fakeGrabber) BuildRequest(_ context.Context, _ *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{Spec: &metadatav1.RequestSpec{}}, nil
}

func (g *fakeGrabber) Convert(_ context.Context, req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	g.mu.Lock()
	g.converts = append(g.converts, req.GetQuery())
	g.mu.Unlock()
	g.grabs <- struct{}{}
	if g.convertErr != nil {
		return nil, g.convertErr
	}
	if g.writePath != "" {
		if err := os.MkdirAll(filepath.Dir(g.writePath), 0o755); err != nil {
			return nil, err
		}
		if err := os.WriteFile(g.writePath, grabPayload, 0o644); err != nil {
			return nil, err
		}
	}
	if len(g.warnings) > 0 {
		return &metadatav1.ConvertResult{Warnings: g.warnings}, nil
	}
	st, _ := structpb.NewStruct(map[string]any{"thumbnail_path": g.writePath})
	return &metadatav1.ConvertResult{Metadata: st}, nil
}

func (*fakeGrabber) Merge(context.Context, *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	return &metadatav1.MergeResult{}, nil // unused by the executor; interface compliance only
}

// matchCount / convertCount / seekSeconds / lastParsed are the test's read side.
func (g *fakeGrabber) matchCount() int {
	g.mu.Lock()
	defer g.mu.Unlock()
	return len(g.parsed)
}

func (g *fakeGrabber) convertCount() int {
	g.mu.Lock()
	defer g.mu.Unlock()
	return len(g.converts)
}

func (g *fakeGrabber) seekSeconds(t *testing.T, call int) float64 {
	t.Helper()
	g.mu.Lock()
	defer g.mu.Unlock()
	if call >= len(g.converts) {
		t.Fatalf("fakeGrabber: convert call %d not recorded (%d total)", call, len(g.converts))
	}
	return g.converts[call].GetFields()["seek_seconds"].GetNumberValue()
}

func (g *fakeGrabber) lastParsed(t *testing.T) *structpb.Struct {
	t.Helper()
	g.mu.Lock()
	defer g.mu.Unlock()
	if len(g.parsed) == 0 {
		t.Fatal("fakeGrabber: no Match call recorded")
	}
	return g.parsed[len(g.parsed)-1]
}

// testThumbPath replicates the plugin's deterministic thumbnail scheme
// (<dataDir>/thumbs/<sha16(seriesRel)>/<sha16(rel)>.jpg) — the D-1 contract
// the re-grab overwrite relies on.
func testThumbPath(t *testing.T, dataDir, seriesRel, rel string) string {
	t.Helper()
	sha16 := func(s string) string {
		sum := sha256.Sum256([]byte(s))
		return hex.EncodeToString(sum[:])[:16]
	}
	return filepath.Join(dataDir, "thumbs", sha16(seriesRel), sha16(rel)+".jpg")
}

// testEpisodeDoc assembles a stored serial-episode document: parsed video
// facts, a probe duration (1 h), and a stale frame-grabber fact.
func testEpisodeDoc(t *testing.T, thumbPath string) []byte {
	t.Helper()
	raw, err := json.Marshal(map[string]any{
		"parsed": map[string]any{
			"absolute_path":        "/media/shows/s01e01.mkv",
			"relative_path":        "s01e01.mkv",
			"series_relative_path": "show",
		},
		"ffprobe": map[string]any{"format": map[string]any{"duration": "3600"}},
		"sources": map[string]any{
			"frame-grabber": map[string]any{"thumbnail_path": thumbPath, "grabbed_at": "2026-01-01T00:00:00Z"},
		},
	})
	if err != nil {
		t.Fatalf("marshal episode doc: %v", err)
	}
	return raw
}

// testRegrabber builds an executor against the fakes with a short timeout
// (the direct regrab calls run synchronously; 5 s is a hang guard, not a
// knob under test).
func testRegrabber(st *fakeThumbStore, src *fakeThumbSources) *thumbRegrabber {
	return &thumbRegrabber{
		store:    st,
		sources:  src,
		debounce: 60 * time.Second,
		timeout:  5 * time.Second,
		lastPos:  make(map[string]float64),
	}
}

// waitForGrabs polls until n Convert calls have been recorded (the accepted
// re-grabs run on their own goroutines), failing after a bounded deadline.
func waitForGrabs(t *testing.T, g *fakeGrabber, n int) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for g.convertCount() < n {
		if time.Now().After(deadline) {
			t.Fatalf("fakeGrabber: %d converts recorded, want %d", g.convertCount(), n)
		}
		time.Sleep(5 * time.Millisecond)
	}
}

// TestThumbRegrabAtStopPosition covers delta scenario 1: a stop ≥ 60 s past
// the last grab runs Convert with seek_seconds = the saved position, the
// JPEG bytes at the deterministic path are replaced, and the stored document
// is unchanged.
func TestThumbRegrabAtStopPosition(t *testing.T) {
	dataDir := t.TempDir()
	thumb := testThumbPath(t, dataDir, "show", "s01e01.mkv")
	if err := os.MkdirAll(filepath.Dir(thumb), 0o755); err != nil {
		t.Fatalf("mkdir thumbs dir: %v", err)
	}
	if err := os.WriteFile(thumb, []byte("stale-default-seek-frame"), 0o644); err != nil {
		t.Fatalf("write stale thumb: %v", err)
	}

	doc := testEpisodeDoc(t, thumb)
	st := &fakeThumbStore{item: store.Item{ID: "itm_1", MediaType: "tv", Document: doc}}
	g := newFakeGrabber(true)
	g.writePath = thumb
	r := testRegrabber(st, &fakeThumbSources{src: g})

	r.regrab(context.Background(), "itm_1", 3720)

	if got, want := g.convertCount(), 1; got != want {
		t.Fatalf("convert calls = %d, want %d", got, want)
	}
	if got, want := g.seekSeconds(t, 0), float64(3720); got != want {
		t.Fatalf("seek_seconds = %v, want %v", got, want)
	}
	// The probe duration surfaced into parsed so Convert can clamp the seek.
	if d := g.lastParsed(t).GetFields()["probe_duration_seconds"].GetNumberValue(); d != 3600 {
		t.Fatalf("parsed probe_duration_seconds = %v, want 3600", d)
	}
	// D-1: bytes at the deterministic path replaced, document untouched.
	got, err := os.ReadFile(thumb)
	if err != nil {
		t.Fatalf("read re-grabbed thumb: %v", err)
	}
	if string(got) != string(grabPayload) {
		t.Fatalf("thumb bytes = %q, want %q", got, grabPayload)
	}
	if string(st.item.Document) != string(doc) {
		t.Fatalf("stored document changed: %s", st.item.Document)
	}
}

// TestThumbRegrabDebounce covers delta scenario 2: writes within 60 s of the
// last grabbed position produce exactly one re-grab, and a later write
// crossing the 60-second delta re-grabs again.
func TestThumbRegrabDebounce(t *testing.T) {
	st := &fakeThumbStore{item: store.Item{ID: "itm_1", MediaType: "tv", Document: testEpisodeDoc(t, "unused.jpg")}}
	g := newFakeGrabber(true)
	r := testRegrabber(st, &fakeThumbSources{src: g})

	ctx := context.Background()
	r.onProgress(ctx, "itm_1", 100) // first grab for the item: accepted
	waitForGrabs(t, g, 1)

	// Player-flush drift a few seconds apart, none crossing the 60 s delta
	// from the last GRABBED position (100): all debounced to zero re-grabs.
	for _, pos := range []int64{110, 130, 150} {
		r.onProgress(ctx, "itm_1", pos)
	}
	// A rejected write never spawns a goroutine, so after the second
	// accepted grab below the count can only be 2 — the settle window is
	// bounded by construction, not by sleep-and-hope.
	r.onProgress(ctx, "itm_1", 200) // delta 100 from the last grab: accepted
	waitForGrabs(t, g, 2)
	r.onProgress(ctx, "itm_1", 210) // delta 10 from the new grab: debounced

	deadline := time.Now().Add(250 * time.Millisecond)
	for time.Now().Before(deadline) {
		if n := g.convertCount(); n != 2 {
			t.Fatalf("convert calls = %d, want exactly 2 (re-grab not debounced)", n)
		}
		time.Sleep(25 * time.Millisecond)
	}
	if n := g.convertCount(); n != 2 {
		t.Fatalf("convert calls = %d, want exactly 2", n)
	}
}

// TestThumbRegrabFailureSkipped covers delta scenario 3: a plugin
// unavailable, a declining Match, and a failing Convert are each logged and
// skipped — no panic out of the executor, no bytes written, stored document
// unchanged.
func TestThumbRegrabFailureSkipped(t *testing.T) {
	t.Run("plugin unavailable", func(t *testing.T) {
		st := &fakeThumbStore{item: store.Item{ID: "itm_1", MediaType: "tv", Document: testEpisodeDoc(t, "unused.jpg")}}
		r := testRegrabber(st, &fakeThumbSources{err: errors.New("frame-grabber not serving")})

		r.regrab(context.Background(), "itm_1", 3720) // must not panic

		if string(st.item.Document) == "" {
			t.Fatal("stored document vanished")
		}
	})

	t.Run("match declines", func(t *testing.T) {
		st := &fakeThumbStore{item: store.Item{ID: "itm_1", MediaType: "tv", Document: testEpisodeDoc(t, "unused.jpg")}}
		g := newFakeGrabber(false) // e.g. a serial-record document
		g.reason = "series document, not an episode"
		r := testRegrabber(st, &fakeThumbSources{src: g})

		r.regrab(context.Background(), "itm_1", 3720)

		if n := g.convertCount(); n != 0 {
			t.Fatalf("convert calls = %d, want 0 after a declined match", n)
		}
	})

	t.Run("convert fails", func(t *testing.T) {
		dataDir := t.TempDir()
		thumb := testThumbPath(t, dataDir, "show", "s01e01.mkv")
		doc := testEpisodeDoc(t, thumb)
		st := &fakeThumbStore{item: store.Item{ID: "itm_1", MediaType: "tv", Document: doc}}
		g := newFakeGrabber(true)
		g.convertErr = errors.New("ffmpeg exited 1")
		r := testRegrabber(st, &fakeThumbSources{src: g})

		r.regrab(context.Background(), "itm_1", 3720) // must not panic

		if _, err := os.Stat(thumb); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("thumb stat err = %v, want not-exist (no bytes written on failure)", err)
		}
		if string(st.item.Document) != string(doc) {
			t.Fatalf("stored document changed: %s", st.item.Document)
		}
	})
}
